#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

struct Cell { int* p; explicit Cell(int x): p(new int(x)) {} ~Cell() { delete p; } Cell(const Cell&) = delete; Cell& operator=(const Cell&) = delete; Cell& operator=(Cell&& x) noexcept { if (this != &x) { delete p; p = std::exchange(x.p, nullptr); } return *this; } int get() const { return p ? *p : 0; } };
int solve(int a, int b) { Cell x{a}, y{b}; x = std::move(y); Cell& alias = x; x = std::move(alias); return x.get() + y.get(); }
